-- Object descriptions state each object's current guarantee. Installations
-- that adopted the release baseline receive the same descriptions a fresh
-- installation of it carries.
SET statement_timeout = 0;
SET idle_in_transaction_session_timeout = 0;
SET client_encoding = 'UTF8';
SET standard_conforming_strings = on;
SET client_min_messages = warning;

COMMENT ON TABLE public.hrm_comp_cycles IS 'HRM merit rounds: draft, open, in_review, approved, pushed, closed (or cancelled) with the date new rates take effect, the budget basis, and the matrix-or-formula guideline evaluated by the fixed-grammar service evaluator.';
COMMENT ON TABLE public.crew_time_batches IS 'Field crew batches: foreman batch per project per day with signed submit and multi-stage approval; posting creates time_entries.';
COMMENT ON COLUMN public.documents.payment_card_id IS 'Funding card: the card_charge/refund instrument, or the single corporate card backing the company_paid and personal lines of an expense_report (one card per report)';
COMMENT ON COLUMN public.documents.ship_to_country IS 'Frozen sale destination country: the jurisdiction the document was taxed/posted with. Stamped by the posting kernel for customer invoices/credits; the nexus ledger reads this (then quote evidence) and reports the rest as unattributed — never the live address book.';
COMMENT ON COLUMN public.documents.ship_to_region IS 'Frozen sale destination region/state: see ship_to_country.';
COMMENT ON FUNCTION public.document_close_module(p_kind text) IS 'openbooks:document-close-module:v2 - table-driven registry (openbooks_document_close_modules) mirroring DOCUMENT_CLOSE_MODULES; unknown kinds yield null';
COMMENT ON FUNCTION public.employment_assignment_versions_closure_guard() IS 'openbooks:employment_assignment_versions_closure_guard:v2 - closed rows immutable; live rows accept only the closing transition or a pure audit touch; successor + evidence proven deferred by hrm_closure_evidence_guard; v2 adds position_id to the content allowlist so a closure cannot repoint the position link';
COMMENT ON COLUMN public.stock_count_lines.is_pre_guard_legacy IS 'True for lines that predate the duplicate-subject and non-negative guards on an immutable (posted or cancelled) count and are preserved as evidence: exempt from the duplicate-subject unique index and the non-negative CHECK. Never set on new writes.';
COMMENT ON CONSTRAINT stock_count_lines_counted_nonnegative ON public.stock_count_lines IS 'A physical count is never negative: an empty bin counts 0. A negative count would post a phantom negative variance; rows marked is_pre_guard_legacy predate the guard on an immutable count and are preserved as evidence (provenance in upgrade_legacy_provenance).';
COMMENT ON FUNCTION public.je_guard() IS 'openbooks:je_guard:v7 - append-only kernel guard for journal entry mutations with the reversal-evidence branch and the soft-close-aware delete fence; amend escapes are refused by design';
COMMENT ON FUNCTION public.jl_check_account() IS 'openbooks:jl_check_account:v6 - locks the tenant-coherent account row before validating a direct journal-line write; evidence-only stamps are not re-validated as postings; the inactive-account refusal names the remedy; a merged account refuses every posting and names its survivor';
COMMENT ON FUNCTION public.lease_charges_base_rent_repair() IS 'openbooks:lease_charges_base_rent_repair:v2 - explicit, idempotent maintenance repair for overlapping base-rent charges; it is never invoked automatically, and each conflict contributes to the cumulative cancelled-line total while billed evidence remains untouched';
COMMENT ON TABLE public.hrm_leave_requests IS 'HRM leave requests: lifecycle draft/submitted/approved/rejected/withdrawn/cancelled. Approved requests never overlap per employment (storage exclusion); the service refuses overlapping submits first.';
COMMENT ON TABLE public.hrm_offers IS 'HRM proposed terms: at most one live offer per application (partial unique index), with send/respond evidence and the hire change request link. Terminal rows immutable; deletes only on the governed amend path.';
COMMENT ON FUNCTION public.openbooks_clone_authority() IS 'True only inside the deterministic clone transaction: openbooks.clone, openbooks.migration and openbooks.amend asserted together with an unscoped maintenance context (public.app_bypass_rls_active() or a BYPASSRLS login). Guards honour it for INSERT of posted history only; it never permits UPDATE, DELETE, or tenant-transaction writes.';
COMMENT ON FUNCTION public.openbooks_reversal_mirrors(p_org_id uuid, p_original_id uuid, p_reversal_id uuid) IS 'openbooks:reversal-mirror:v1 - true when the reversal entry lines mirror-negate the original entry lines; memo/due-date/custom metadata excluded';
COMMENT ON FUNCTION public.payroll_employment_coherence_guard() IS 'Payroll employment coherence: refuses any payroll row whose employment_id names an employment of a different worker. Cross-org/unknown ids are the composite tenant FK''s job at commit; this trigger owns only the cross-person refusal and names both ids.';
COMMENT ON COLUMN public.change_orders.income_account_id IS 'Income account the approval lands on the created SOV line when the change order has no target schedule line (nullable for older rows, which resolve through the org project-revenue control account at approval time)';
COMMENT ON CONSTRAINT crm_forecast_snapshot_target ON public.crm_forecast_snapshots IS 'Snapshot target is at most one of owner/team: neither means the whole organization';
COMMENT ON COLUMN public.crm_opportunity_lines.unit_cost IS 'Expected cost per unit in the opportunity currency. NULL = cost not recorded, which is not the same as zero: an uncosted line has no margin, a zero-cost line has a 100% margin. May exceed unit_price — a deal sold below cost is representable on purpose';
COMMENT ON COLUMN public.crm_opportunity_lines.cost_amount IS 'quantity x unit_cost, extended and rounded by the writer exactly as amount extends unit_price, so a reader never re-derives it. NULL if and only if unit_cost is NULL';
COMMENT ON CONSTRAINT crm_opportunity_line_cost ON public.crm_opportunity_lines IS 'Cost is non-negative and all-or-nothing: cost_amount is a stored derivation of unit_cost, so a row carrying one without the other would carry a derivation nobody can reproduce';
COMMENT ON COLUMN public.crm_opportunity_statuses.requires_lines IS 'Entering this stage requires at least one opportunity line. Declared per status, enforced by the engine resolver validateOpportunityStageTransition on every write path';
COMMENT ON COLUMN public.crm_opportunity_statuses.requires_primary_contact IS 'Entering this stage requires a primary contact on the opportunity';
COMMENT ON COLUMN public.crm_opportunity_statuses.requires_positive_amount IS 'Entering this stage requires a projected amount strictly greater than zero. The baseline CHECK already forbids a negative projected amount, so this is the "priced, not merely non-negative" gate';
COMMENT ON COLUMN public.crm_opportunity_statuses.requires_win_loss_reason IS 'Entering this stage requires a win/loss reason. Backfilled true on every existing closed-and-not-won status so upgrades keep the rule the edit route used to hard-code; a new status gates nothing until configured';
COMMENT ON COLUMN public.depreciation_schedules.convention IS 'First-period convention the retained schedule was built under (full_month, mid_month, half_year). Compared by the post-posting drift gate like method and life; NULL means the convention was never recorded.';
COMMENT ON COLUMN public.document_lines.settlement_type IS 'Who fronted the money for this expense line: out_of_pocket = employee paid, company owes a person; company_paid = company-liability card, company owes the issuer; personal = non-business charge on the company card, employee owes the company (receivable, never an expense). NULL = settlement not recorded (all pre-0171 history); the repost path treats NULL as out_of_pocket legacy math';
COMMENT ON COLUMN public.employee_payroll_profiles.country IS 'Statutory country pack this employee runs under: no default — an unset country is refused by NOT NULL rather than silently becoming Canada. Historical rows carrying ''CA'' may have been defaulted; they are left untouched because a defaulted row is indistinguishable from a chosen one.';
COMMENT ON COLUMN public.employee_payroll_profiles.pl_rok_urodzenia IS 'Employee birth year for the PL FP age bar: PESEL-derived with a declared fallback for employees without a PESEL; null = unknown, never guessed.';
COMMENT ON COLUMN public.employee_payroll_profiles.es_ano_nacimiento IS 'Employee birth year feeding the ES age-banded rule, AÑOPER; null = unknown, never guessed.';
COMMENT ON COLUMN public.employee_payroll_profiles.es_grupo_cotizacion IS 'ES Seguridad Social contribution group 1–11, Orden PJC/297/2026 art. 33; null = undeclared, never group 1 by fallthrough.';
COMMENT ON COLUMN public.employee_payroll_profiles.es_situacion_laboral IS 'ES employment situation SITUPER: activo, pensionista or desempleado; null = undeclared, never defaulted.';
COMMENT ON COLUMN public.employee_payroll_profiles.jp_hyojun_hoshu IS 'Employee 標準報酬月額 grade value in whole yen, copied off the JPS notice; null = undeclared, never priced off raw pay.';
COMMENT ON COLUMN public.employee_payroll_profiles.jp_kaigo_dainigou IS 'Whether the employee is a 介護保険第2号被保険者, as "true"/"false" text; null = undeclared, never defaulted into the cheaper premium.';
COMMENT ON COLUMN public.employee_payroll_profiles.br_dependentes IS 'Dependent count for the R$ 189,59 IRRF deduction, from the eSocial cadastro; null = unknown, never defaulted.';
COMMENT ON COLUMN public.employee_payroll_profiles.br_pensao_mensal IS 'Court-ordered monthly alimony reducing the IRRF base; null = none ordered, never zero-filled.';
COMMENT ON COLUMN public.employee_payroll_profiles.br_salario_familia_filhos IS 'Qualifying children for salário-família (<14 or disabled), from the eSocial cadastro; null = none declared, never defaulted.';
COMMENT ON COLUMN public.employee_payroll_profiles.es_contrato_temporal IS 'ES contract type for the Seguridad Social desempleo split: "true" prices the temporary-contract 8,30% rate, "false" the indefinite 7,05% (Orden PJC/297/2026 art. 33.2.a); null = undeclared, never indefinite by fallthrough.';
COMMENT ON CONSTRAINT employee_payroll_profiles_country ON public.employee_payroll_profiles IS 'Pack-country shape check: two uppercase letters. Deliberately NOT an enumeration — packs declare which countries exist (engine/src/payroll/packs.ts), the database only rejects malformed codes.';
COMMENT ON COLUMN public.entitlement_ledger.source_holiday_key IS 'Statutory holiday that granted this movement (e.g. remembrance_day), with source_holiday_date.';
COMMENT ON COLUMN public.entitlement_ledger.source_holiday_date IS 'Date of the statutory holiday that granted this movement; pairs with source_holiday_key.';
COMMENT ON COLUMN public.entitlement_ledger.take_on IS 'Day the alternate-day entitlement must be taken: the next scheduled workday default, or the audited agreed date.';
COMMENT ON CONSTRAINT entitlement_plans_alternate_shape ON public.entitlement_plans IS 'The alternate-day binding is hours-denominated, manual (granted by the holiday rule, never accrued), and accrue-direction.';
COMMENT ON CONSTRAINT entitlement_plans_hours_no_percent_accrual ON public.entitlement_plans IS 'An hours-denominated plan cannot accrue a percent of (money) earnings: the dollars would be stored as hours. Accrue per_hour_worked or fixed_per_period, or bank money.';
COMMENT ON CONSTRAINT entitlement_plans_system_key ON public.entitlement_plans IS 'Engine bindings a plan may claim: vacation, or the statutory alternate-day-off bank granted by work-triggered holiday rules.';
COMMENT ON TABLE public.item_rate_version_profiles IS 'Per-(version, item) pin of the pricing policy, base unit and invoice presentation in force when that rate version was saved. Resolution reads the selected version''s pin; item_rate_profiles keeps only the defaults for new versions.';
COMMENT ON COLUMN public.journal_lines.source_cleared_date IS 'Source-system cleared date mirrored as evidence: the day the source connector reports this line cleared. Set once by the mirror; never edited.';
COMMENT ON COLUMN public.parties.emergency_contact IS 'Self-service: the person''s emergency contact as {name, relationship, phone}; null = none recorded. Proposed by the person through a profile_change request, applied on HR approval; masked (null_out) in sandboxes.';
COMMENT ON CONSTRAINT pay_components_country ON public.pay_components IS 'Pack-country shape check: NULL (shared component) or two uppercase letters. Deliberately NOT an enumeration — packs declare which countries exist (engine/src/payroll/packs.ts), the database only rejects malformed codes.';
COMMENT ON CONSTRAINT pay_components_kind ON public.pay_components IS 'Component kinds: earning, deduction, employer_contribution, credit. Credit pays a refundable employment credit the employer reclaims from the tax authority (engine/src/payroll/packs.ts).';
COMMENT ON CONSTRAINT pay_components_tax_treatment ON public.pay_components IS 'Treatment shape check: non-empty lower-snake identifier. Deliberately NOT an enumeration — packs declare which treatments exist (PayrollCountryPack.deductionTreatments, enforced at the API boundary by payComponentTreatmentProblem); the database only rejects malformed values.';
COMMENT ON COLUMN public.pay_stub_lines.liability_account_source IS 'commit = stamped by the committing engine; legacy_component = backfilled from the component''s account for a line committed before the engine stamped one; unknown = such a line whose component named no account (resolves through the pack''s legacy slot).';
COMMENT ON CONSTRAINT pay_stub_lines_kind ON public.pay_stub_lines IS 'Stub line kinds: mirrors pay_components_kind so every seedable component kind is payable.';
COMMENT ON COLUMN public.payment_runs.file_created_at IS 'Instant the run''s first bank file was created. Stamped once via coalesce on first generation and reused by every later render, so re-downloads reproduce byte-identical files and the bank''s duplicate-file detection still recognizes an accidental re-upload of the same run.';
COMMENT ON COLUMN public.payment_runs.file_id_modifier IS 'NACHA File ID Modifier (single character A-Z, 0-9) allocated for this run''s bank file. Pinned once per bank profile per creation day (lowest free letter) so two files generated the same day never share the bank''s same-day duplicate-file identity; null means allocated before this migration and readers fall back to the legacy run-number derivation.';
COMMENT ON TABLE public.payroll_employer_levy_opening IS 'Employer-scope payroll carry-ins: pre-adoption employer base per (org, tax year, levy, region) for pack-declared aggregate levies. Read with committed stub factors to form the annual room; written by the carry-in save under the levy fence. RLS follows the org_id policy like every tenant table.';
COMMENT ON COLUMN public.payroll_statutory_rates.source_citation IS 'The published source the entered figures were taken from (for example the ESD premium announcement for the year). Null for rows recorded before this change; required by the write boundary on every new or changed row.';
COMMENT ON COLUMN public.payroll_statutory_rates.reason IS 'Why the row was entered or changed, in the operator''s own words. Null for rows recorded before this change; required by the write boundary on every new or changed row.';
COMMENT ON COLUMN public.performance_obligations.legacy_reconciled_at IS 'When the operator attested this obligation''s existing schedule against the policy actually in force at its creation, lifting the legacy-rebuild refusal. NULL until reconciled.';
COMMENT ON COLUMN public.performance_obligations.legacy_reconciled_by IS 'Actor who recorded the legacy reconciliation.';
COMMENT ON COLUMN public.performance_obligations.legacy_reconciliation_reason IS 'Why the operator trusts the existing schedule (e.g. the signed policy memo it was verified against). Required when reconciled.';
COMMENT ON TABLE public.price_level_activation_history IS 'Versioned price-level activation: one [active_from, active_to) period per activation. Historical pricing reads the period covering the transaction date; the live is_active flag governs today and the future only.';
COMMENT ON COLUMN public.recognition_rules.version IS 'Successor-chain version for effective-dated rule policy. A policy edit on a rule referenced by any obligation creates a successor row with version + 1 instead of rewriting this row.';
COMMENT ON COLUMN public.recognition_rules.superseded_by IS 'Forward link to the successor recognition_rules row that replaced this version. NULL while the version is current.';
COMMENT ON COLUMN public.recognition_schedules.transaction_currency IS 'Plan-line currency of the originating transaction (invoice currency; owner functional currency for project obligations). Deferred revenue is recognized out in this currency.';
COMMENT ON COLUMN public.recognition_schedules.transaction_fx_rate IS 'Historical FX rate the originating transaction deferred at; recognition converts plan lines at this rate, never revalued. Amendment bookRates (change_basis) take precedence when present.';
COMMENT ON COLUMN public.reconciliations.evidence_kind IS 'What the sign-off stands on: statement = matched imported statement lines; source = the connector-mirrored cleared evidence, with no statement lines invented.';
COMMENT ON COLUMN public.recurring_schedules.anchor_day IS 'Day-of-month the schedule cadence pins to. Each next run date advances the year-month and clamps this day into the target month, so month-end starts do not drift. Null behaves as the next run date''s day.';
COMMENT ON TABLE public.source_reconciliation_state IS 'Source-system reconciliation state mirrored as evidence: per reconcilable account, the connector key, the last reconciled-through date the mirror derived from cleared markers, and the source statement balance where the source states one.';
COMMENT ON COLUMN public.stock_counts.subsidiary_id IS 'Owning legal entity whose stock the count snapshots and whose books receive its variances: the snapshot, the drift check, and every adjustment movement are scoped to this subsidiary, never inferred from the posting session.';
COMMENT ON COLUMN public.subscriptions.anchor_day IS 'Day-of-month the billing cadence pins to. Each next bill date advances the year-month and clamps this day into the target month, so month-end starts do not drift. Null behaves as the start date''s day.';
COMMENT ON COLUMN public.tax_filings.functional_currency IS 'Frozen denomination of the stored boxes: the filing entity functional currency, or the presentation currency for a translated view. Backfilled where the org posture is unambiguous; NULL means pre-snapshot and ambiguous — readers must refuse, never substitute the current org base.';
COMMENT ON COLUMN public.tax_filings.presentation_currency IS 'Declared presentation currency of a translated consolidated view; NULL for single-currency returns.';
COMMENT ON COLUMN public.tax_filings.translation IS 'Translation evidence for a translated consolidated view: rate source, rate date and per-entity applied rates. NULL for single-currency returns.';
COMMENT ON COLUMN public.tax_filings.subsidiary_ids IS 'Frozen filing-entity scope: the subsidiary set the return summed. NULL means pre-snapshot (unknown scope — v1 semantics); an empty array is the legacy degenerate org-wide return.';
COMMENT ON COLUMN public.tax_filings.registration_id IS 'Frozen filing identity: the tax_registrations row whose number travels on the return. NULL means pre-snapshot or unregistered.';
COMMENT ON COLUMN public.tax_filings.registration_number IS 'Frozen filing identity: the government registration number printed on the return. NULL means pre-snapshot or unregistered.';
COMMENT ON COLUMN public.tax_filings.snapshot_version IS 'Snapshot schema version: 1 hashed form/period/channel/boxes/adjustments only; 2 additionally hashes registration, currency and scope posture. Existing rows stay 1 so they verify exactly as prepared.';
COMMENT ON COLUMN public.tax_return_forms.notice_key IS 'Pack-declared filing-notice catalog key: a tax-namespace message key the generic prepare panel renders for this form, e.g. submission.gst34Notice. NULL = the form declares no notice. Written by pack provisioning on install and reset; never a country branch in UI code';
COMMENT ON TABLE public.upgrade_legacy_provenance IS 'Shared registry of rows whose pre-upgrade history was backfilled, not recorded. Readers refuse or label by (org, migration, table, row) membership; notes are human evidence, never read keys.';
COMMENT ON COLUMN public.upgrade_legacy_provenance.table_name IS 'Subject table of the legacy row (e.g. recognition_rules). No row FK by design: one registry points at many tables; integrity comes from the upgrade backfill that recorded the row.';
COMMENT ON COLUMN public.vendor_pay_applications.revision IS 'Optimistic-concurrency token for draft line edits. The line update requires the revision its editor read and bumps it on success, so concurrent editors cannot silently overwrite each other''s certified inputs.';
COMMENT ON TABLE public.ai_capabilities IS 'HRM AI rails: code-registry mirror of AI capabilities per org; autonomy may only be edited down from the code maximum.';
COMMENT ON TABLE public.ai_decisions IS 'HRM AI rails: append-only AI decision log — digests never prompts, one-line PII-free summaries, cited sources, outcomes, human reviewers.';
COMMENT ON TABLE public.ai_rails_settings IS 'HRM AI rails: org-declared thresholds, cohort key, bias terms and review cadence; Setup owns the UI.';
COMMENT ON TABLE public.anomaly_baselines IS 'HRM AI rails: per-cohort mean/stddev windows for the anomaly baseline rules.';
COMMENT ON COLUMN public.api_keys.scopes IS 'Explicit subset of the permission catalogue this key grants (intersected with the owner''s effective permissions at request time). Never empty: legacy empty sets were frozen to the catalogue snapshot on upgrade, and storage rejects new ones.';
COMMENT ON TABLE public.automation_approval_settings IS 'HRM exception-only approval tuning: per-subject thresholds and delegation timing over the existing Flows gates.';
COMMENT ON TABLE public.automation_event_queue IS 'HRM automation trigger staging: durable in-transaction event rows drained by the automations tick; writers never call the engine inline.';
COMMENT ON COLUMN public.automation_event_queue.attempt_count IS 'Automation trigger staging: firing attempts so far; the drain backs off and parks the row dead at the ceiling instead of consuming failures.';
COMMENT ON COLUMN public.automation_event_queue.next_attempt_at IS 'Automation trigger staging: the drain claims only rows due at or before now, so a failed firing retries on backoff rather than every tick.';
COMMENT ON TABLE public.automation_runs IS 'HRM automation run log: append-only evidence of every firing, keyed idempotent so a re-fired trigger never double-runs.';
COMMENT ON TABLE public.automations IS 'HRM automations: org trigger/rule/condition/action recipes versioned on every edit; the builder behind the automations feature.';
COMMENT ON COLUMN public.bank_feed_connections.sync_overlap_days IS 'Re-pull overlap in days before the last successful sync. Wider windows recover late-posting transactions; import dedupes the overlap. Null means the 14-day default.';
COMMENT ON TABLE public.crew_time_batch_events IS 'Field crew batch history: append-only lifecycle evidence; edits after submit are refused, never overwritten.';
COMMENT ON TABLE public.crew_time_batch_lines IS 'Field crew batch lines: one row per worker/time-type/task/cost-code/equipment; equipment pair is all-or-nothing.';
COMMENT ON TABLE public.employment_assignment_versions IS 'HRM assignment versions: title, placement, decimal FTE, and the effective-dated is_primary fact. At most one live primary per employment at any effective time (employment_assignment_versions_single_primary).';
COMMENT ON COLUMN public.employment_assignment_versions.position_id IS 'HRM position link: the funded establishment slot this assignment holds. Title, department and location stay on the assignment version and are never inherited; disagreement with the position version is a service preflight warning.';
COMMENT ON TABLE public.employment_assignments IS 'HRM stable assignment slots: one row per primary/additional slot within an employment. Concurrent same-start assignments are separate rows by design.';
COMMENT ON TABLE public.employment_changes IS 'HRM immutable revision evidence: every version closure appends one row with prior image, non-blank reason, and a users row or named system source. Updates and deletes rejected (employment_changes_immutable_guard).';
COMMENT ON TABLE public.hrm_absences IS 'HRM immutable absence record per day: written when a request is approved or recorded after the fact. Corrections are reversing rows (negative hours via reversal_of), never updates; deletes only on the governed amend path.';
COMMENT ON COLUMN public.hrm_absences.is_pre_guard_legacy IS 'True for absence rows that predate the one-row-per-day guard and share their (employment, day) with another live row. Exempt from the duplicate-day unique index and preserved as evidence: absence rows carry no delete path, so the double-counted day stands. Never set on new writes.';
COMMENT ON TABLE public.hrm_action_reasons IS 'HRM action reason codes: Setup-owned vocabulary per generic HR action; required on submit only while the hrmActionReasons feature is on.';
COMMENT ON TABLE public.hrm_allowance_payroll_inputs IS 'HRM allowance pay-run input seam: ONE ROW PER PER-DIEM OR TRAVEL ENTRY. HR sends AMOUNTS keyed by entry_id — payroll allocates them to pay periods and never recomputes. employee_party_id is the key the run reads; employment_id is provenance only. unique (org_id, entry_kind, entry_id). Voiding never clears consumed_by_run_document_id.';
COMMENT ON TABLE public.hrm_application_events IS 'HRM funnel evidence: the append-only event ledger for every application transition, recorded in the same transaction as the state write. Updates refused on every path; deletes only on the governed amend path.';
COMMENT ON TABLE public.hrm_applications IS 'HRM candidacies: one row per (requisition, candidate) with the current pipeline stage. Terminal rows immutable; deletes only on the governed amend path.';
COMMENT ON TABLE public.hrm_apprentice_ratio_rules IS 'HRM apprentice ratio rules: journey:apprentice ratios per schedule measured daily or weekly. A breach prices the apprentice hours at the journey line — both visible, neither silent.';
COMMENT ON TABLE public.hrm_benefit_award_events IS 'HRM benefit award lifecycle evidence: append-only. Every move appends an event with reason and actor.';
COMMENT ON TABLE public.hrm_benefit_awards IS 'HRM benefit awards: each issuance with immutable program and source snapshots, evidence, lifecycle status, and payroll or external linkage. Corrections void and reissue; never rewrite.';
COMMENT ON TABLE public.hrm_benefit_dependents IS 'HRM covered dependents. display_name is PII and enrolled in sandbox masking like parties.';
COMMENT ON TABLE public.hrm_benefit_enrollments IS 'HRM benefit elections: amounts computed from the plan basis at election and STORED in plan currency. A change ends the active row and opens a new one from the change date — never an in-place rewrite. unique (org_id, employment_id, plan_id, effective_from).';
COMMENT ON TABLE public.hrm_benefit_events IS 'HRM benefit election evidence: append-only. Every lifecycle move appends an event with reason and actor; corrections are new events, never updates.';
COMMENT ON TABLE public.hrm_benefit_payroll_inputs IS 'HRM benefit pay-run input seam: ONE ROW PER ENROLMENT PER COVERAGE MONTH PER KIND. HR sends AMOUNTS (already prorated by the plan rule) — payroll allocates months to pay periods and never recomputes. pay_component_id names the component whose tax_treatment prices the row; employee_party_id is the key the run reads; employment_id is provenance only. unique (org_id, enrollment_id, kind, coverage_from). Voiding never clears consumed_by_run_document_id.';
COMMENT ON TABLE public.hrm_benefit_plan_levels IS 'HRM benefit pricing tiers: one row per tier per plan, the single source of truth for tier pricing. Elections copy tier amounts at elect time; repricing a tier never rewrites history.';
COMMENT ON TABLE public.hrm_benefit_plans IS 'HRM benefit plans: the org''s offered plans with cost bases, the required proration rule, and pay-component links. Tax treatment lives on the pay component, never here. Plan kind is org-declared free text; no pack declares plan kinds.';
COMMENT ON TABLE public.hrm_benefit_program_members IS 'HRM benefit program membership: employments bound to a program over effective dates with weight and role for allocation.';
COMMENT ON TABLE public.hrm_benefit_program_scopes IS 'HRM benefit program measurement scope: typed child table resolving departments and projects through tenant keys. Company scope carries no rows.';
COMMENT ON TABLE public.hrm_benefit_program_sources IS 'HRM benefit program funding sources: typed child table naming the source accounts per program. No overlapping hardcoded account policy.';
COMMENT ON TABLE public.hrm_benefit_programs IS 'HRM employer-defined benefit programs: rewards, allowances, incentives, and custom programs with typed rule columns. Insured plans (hrm_benefit_plans) stay authoritative for health and retirement. Programs close rather than delete; history is preserved.';
COMMENT ON TABLE public.hrm_calibration_sessions IS 'HRM calibration sessions: the rating grid over a review cycle with append-only calibration events as the audit trail.';
COMMENT ON TABLE public.hrm_candidate_consents IS 'HRM candidate consents: one row per (candidate, purpose) with grant, expiry, withdrawal and extension-request evidence. Erasure takes its receipts with it.';
COMMENT ON TABLE public.hrm_candidates IS 'HRM prospects: a name plus contact PII, never a party until hired — the hire transaction links the employee party. Contact PII is masked in sandboxes like parties.';
COMMENT ON TABLE public.hrm_certified_payroll_runs IS 'HRM certified payroll runs: the FROZEN report payload (one row per worker per classification per day) plus the rendered pack artefact. format_key is a pack-declared artefact key; amends_run_id links an amendment to the run it supersedes.';
COMMENT ON TABLE public.hrm_comp_class_rules IS 'HRM comp-class match rules: priority-ordered; the resolver takes the highest-priority match and refuses when nothing matches — never a silent default class.';
COMMENT ON TABLE public.hrm_comp_classes IS 'HRM workers-comp premium classes: the org''s class taxonomy with the rate per 100 where declared. jurisdiction_code is pack vocabulary carried as free text.';
COMMENT ON TABLE public.hrm_comp_cycle_budgets IS 'HRM cycle envelopes: one amount per cycle per department-or-manager holder. The allocated figure is computed at read time from the lines, never stored.';
COMMENT ON TABLE public.hrm_comp_cycle_lines IS 'HRM cycle decisions: one row per cycle per employment with the payroll-side wage snapshotted at open, the stored compa-ratio and guideline range, and the proposal through approval lifecycle. A pushed line already moved payroll.';
COMMENT ON TABLE public.hrm_comp_events IS 'HRM cycle evidence: the append-only event ledger for every cycle transition, recorded in the same transaction as the state write. Updates refused on every path; deletes only on the governed amend path.';
COMMENT ON TABLE public.hrm_comp_statements IS 'HRM total-rewards evidence: frozen per-employment payloads with an optional rendered PDF. Regeneration is a new row; a delivered statement is never overwritten.';
COMMENT ON TABLE public.hrm_compliance_findings IS 'HRM compliance findings: append-only pre-run flags (ratio_breach, missing_rate, class_unresolved, registration_missing, fringe_mismatch) read by the certified-payroll generator and compliance review. Resolve carries its reason; deletes are refused.';
COMMENT ON TABLE public.hrm_data_subject_exports IS 'HRM subject-access exports: the DSAR queue; the worker builds the zip into the File Cabinet for the requester only.';
COMMENT ON TABLE public.hrm_document_categories IS 'HRM document categories: the org-declared Setup vocabulary for template, document, and retention-schedule category keys.';
COMMENT ON TABLE public.hrm_document_events IS 'HRM document events: append-only evidence ledger for every document transition.';
COMMENT ON TABLE public.hrm_document_signers IS 'HRM document signers: ordered signer rows with one consumable HMAC token each and the signing evidence record.';
COMMENT ON TABLE public.hrm_document_templates IS 'HRM document templates: org-authored shells with mustache bodies and declared merge fields; signatures ordered by signer_roles.';
COMMENT ON TABLE public.hrm_documents IS 'HRM documents: one row per issued HR document; the file is the current File Cabinet version, retain_until is stored at completion.';
COMMENT ON TABLE public.hrm_employment_change_requests IS 'Governed HRM employment change proposals. One row binds a frozen payload (storage-computed sha256 digest over canonical jsonb text) to the exact worker_employments revision it was written against and to the native Flows run that decides it. Lifecycle draft -> pending_approval -> approved/rejected/withdrawn, approved -> applied; rejected/withdrawn/applied are terminal and revised proposals are new rows, so no approval is ever re-pointed at edited payload. Canonical mutation stays in employment_changes; approval execution stays in flow_runs/flow_gates; application auth stays in the service — applied_by here is evidence only.';
COMMENT ON TABLE public.hrm_employment_classifications IS 'HRM employment classifications: bitemporal assignment of an employment to a classification with the worker''s home local. History is kept by closing the active row and opening a new one, never by rewriting.';
COMMENT ON TABLE public.hrm_enrollment_windows IS 'HRM enrollment windows: open_enrollment, new_hire, or life_event, with applies_to scoping and draft/open/closed lifecycle. Closing refuses pending elections with a reasoned event each — never silently dropped.';
COMMENT ON TABLE public.hrm_exit_records IS 'HRM exit records: one per terminated employment — reason kind, voluntary/regrettable/rehire flags, the paired exit interview, destination and notes. Corrections update the row; deletes are refused by trigger.';
COMMENT ON TABLE public.hrm_feedback IS 'HRM continuous feedback: append-only praise/feedback/request rows; retraction is a new retraction row linking the original.';
COMMENT ON TABLE public.hrm_goal_updates IS 'HRM append-only goal progress evidence: corrections are new rows; updates are refused by trigger.';
COMMENT ON TABLE public.hrm_goals IS 'HRM per-employment goals: title, due date, exact-decimal weight, active/achieved/missed/cancelled, progress 0..100; achieved requires progress 100.';
COMMENT ON TABLE public.hrm_graph_revisions IS 'HRM reporting-graph serialization counter: bumped by hrm_reporting_no_cycle on every reporting write before the cycle walk. Storage-only concurrency mechanism, never product data.';
COMMENT ON TABLE public.hrm_headcount_plan_lines IS 'HRM planned movements: create (no position until approved), backfill, change, terminate — terminate is informational and never ends an employment. Cost is computed at save with its inputs in cost_basis, never typed.';
COMMENT ON TABLE public.hrm_headcount_plans IS 'HRM workforce plans: one plan per fiscal window, draft, submitted, approved, closed. Lines carry the movements; approval opens requisitions through the recruiting service.';
COMMENT ON TABLE public.hrm_interview_kit_questions IS 'HRM kit questions: suggested interview questions per kit, optionally pinned to one attribute; children of the kit.';
COMMENT ON TABLE public.hrm_interview_kits IS 'HRM structured-interview kits: one named kit per org with an optional pipeline-stage pin, instructions, and the org-declared rating scale. A kit with sittings is history-pinned; deactivate it instead of deleting it.';
COMMENT ON TABLE public.hrm_interview_panel IS 'HRM interview panel membership: join rows between interviews and parties, children of a guarded parent (cascade with the interview).';
COMMENT ON TABLE public.hrm_interview_slots IS 'HRM self-scheduling slots: proposed/booked/declined rows per interview. One booking link covers a proposed batch, so its SHA-256 hex repeats across the batch rows; the raw token is never stored. calendar_ref carries provider event ids — the provider is an org-declared connector, not built here.';
COMMENT ON TABLE public.hrm_interviewer_pools IS 'HRM interviewer pools: named interviewer groups with declared availability windows (never read from a calendar) and an optional default kit.';
COMMENT ON TABLE public.hrm_interviews IS 'HRM interview sittings: one row per interview with kind, schedule, outcome on completion, and optional scorecard. Completed rows immutable; deletes only on the governed amend path.';
COMMENT ON TABLE public.hrm_job_descriptions IS 'HRM job descriptions: reusable posting content a requisition starts from. Requisitions copy the content at creation; an entry referenced by a requisition is history-pinned, so deactivate it instead of deleting it.';
COMMENT ON TABLE public.hrm_job_families IS 'HRM job architecture: stable craft identity per org code. Deactivation preserves history; a family with levels cannot be deleted, only retired.';
COMMENT ON TABLE public.hrm_job_levels IS 'HRM job architecture: one rung per ladder per org code, NULL family = the org-wide ladder. Rank orders the ladder; equal_value_criteria carries the org-declared gender-neutral criteria the EU directive requires.';
COMMENT ON TABLE public.hrm_job_postings IS 'HRM job-board postings: one posting per (requisition, board_key). board_key is an org-declared connector key; the generic layer ships internal and feed. A posting with applicants or events is history-pinned.';
COMMENT ON TABLE public.hrm_leave_policies IS 'HRM leave policies: HR entitlement in TIME per type, with applies_to scoping and effective dating. This is not the payroll bank in VALUE; the two are never conflated.';
COMMENT ON TABLE public.hrm_leave_types IS 'HRM leave-type taxonomy: org-configurable, country-agnostic. value_crossing names which of the two allowed pay-run input movements (payout, bank_in) this type raises, or none. No pack declares leave types; this table is the single source of truth.';
COMMENT ON TABLE public.hrm_offer_templates IS 'HRM offer templates: mustache body plus clause rows with an approval flag. A template with offers is history-pinned; deactivate it instead of deleting it.';
COMMENT ON TABLE public.hrm_offer_versions IS 'HRM offer regeneration evidence: every render appends a version, never an overwrite. Append-only.';
COMMENT ON TABLE public.hrm_one_on_ones IS 'HRM 1:1 meetings: scheduled conversations between a manager employment and a report employment; recurrence is a rule, never pre-generated rows.';
COMMENT ON TABLE public.hrm_pay_bands IS 'HRM SHOULD-pay: versioned min/target/max rows per scope with an overlap exclusion — a band change is a new row, never an overwrite of a row a cycle line cited. Never what anyone IS paid.';
COMMENT ON TABLE public.hrm_pay_gap_snapshots IS 'HRM pay-equity evidence: frozen Article 9 metrics computed from payroll truth with per-category gaps and the OLS unexplained gap. Frozen at generation — a new snapshot supersedes, never edits.';
COMMENT ON TABLE public.hrm_pay_information_requests IS 'HRM worker pay-information requests: due at request plus the org-declared response days; fulfilment points at the frozen snapshot whose category averages answered the worker.';
COMMENT ON TABLE public.hrm_payroll_inputs IS 'HRM pay-run input queue: ONE ROW PER ABSENCE DAY for payout/bank_in types. HR sends HOURS only — there is deliberately NO amount column; the run resolves the rate. employee_party_id is the key the ledger reads; employment_id is provenance only and the two are never interchangeable. unique (org_id, source_leave_request_id, absence_date). Voiding never clears consumed_by_run_document_id (the only link back to the stale run).';
COMMENT ON TABLE public.hrm_per_diem_entries IS 'HRM per-diem entries: one computed row per employment per project per day. unique (org_id, employment_id, project_id, worked_on). A void carries its reason; voided rows stay voided.';
COMMENT ON TABLE public.hrm_per_diem_policies IS 'HRM per-diem policies: org-declared computation rules per basis (flat_daily, distance_brackets, hours_threshold). rules shape is validated by the service''s zod schema per basis; taxable is an org declaration the pack interprets. The linked pay component must be kind earning (amounts paid to the worker price as earnings; taxability rides tax_treatment).';
COMMENT ON TABLE public.hrm_pipeline_stages IS 'HRM pipeline rows: ordered stages with a stable key and a kind (screening, interview, assessment, offer, hired, rejected). Terminality derives from kind; the funnel ends exactly in hired or rejected.';
COMMENT ON TABLE public.hrm_pipeline_templates IS 'HRM recruiting funnels: one ordered pipeline per org name with a single default. Deactivation preserves history; a template that opened requisitions cannot be deleted.';
COMMENT ON TABLE public.hrm_posting_events IS 'HRM posting evidence: the append-only event ledger for publishes, pauses, closes, received applications, sent dispositions and errors. Append-only.';
COMMENT ON TABLE public.hrm_process_steps IS 'HRM runtime checklist rows: snapshot copies of the template steps with concrete due dates. Done steps carry who/when evidence; skipped steps carry a reason; attachment evidence names a same-org file the actor may read.';
COMMENT ON TABLE public.hrm_process_template_steps IS 'HRM process checklist rows: ordered steps with owner, due offset relative to the process effective date (may be negative), and evidence kind. Copied as a snapshot when a process opens; later edits never rewrite history.';
COMMENT ON TABLE public.hrm_process_templates IS 'HRM process checklist configuration: one ordered checklist per (kind, name) with an applies_to filter (employer subsidiary / department, null = all). Deactivation preserves history; a template that opened processes cannot be deleted.';
COMMENT ON TABLE public.hrm_processes IS 'HRM runtime checklists: one row per employment start, end, or transfer, opened in the same transaction as the approved change request (opened_by_change_id) or manually. At most one open process of a kind per employment; terminal rows immutable; deletes only on the governed amend path.';
COMMENT ON TABLE public.hrm_qualification_alerts IS 'HRM qualification alerts: one row per (qualification, lead_days), written idempotently by the daily scan; sent_at null is due but undelivered.';
COMMENT ON TABLE public.hrm_qualification_events IS 'HRM qualification evidence: append-only; renewals link the new row to the old one, warned records a warn-severity dispatch that proceeded.';
COMMENT ON TABLE public.hrm_qualification_requirements IS 'HRM dispatch requirements: what a project, equipment, position or classification demands. block refuses the assignment by name; warn records a warned event.';
COMMENT ON TABLE public.hrm_qualification_settings IS 'HRM qualification settings: the org extended category vocabulary and default alert lead-day schedule.';
COMMENT ON TABLE public.hrm_qualification_types IS 'HRM qualification taxonomy: org-declared codes through Setup. category is base-six plus the org extra list in hrm_qualification_settings (trigger-guarded); validity_months null never expires.';
COMMENT ON TABLE public.hrm_rate_schedule_lines IS 'HRM rate schedule lines: one resolvable rate per schedule per classification per effective date. unique (schedule_id, classification_id, effective_from). fringe_rate is cash fringe; fringe_credit_rate is fringe paid to plans and creditable against the obligation.';
COMMENT ON TABLE public.hrm_rate_schedules IS 'HRM rate schedules: prevailing-wage, union-agreement, or org-declared tables with structured applies_to scoping plus project_ids and location_ids arrays. jurisdiction_code is pack vocabulary carried as free text; reciprocity is the org''s declared home_local / jobsite_local / higher_of rule.';
COMMENT ON TABLE public.hrm_requisitions IS 'HRM vacancy openings: one row per vacancy against a position or a planned headcount, with an org-sequence number, headcount versus filled_count (filled only through hire), an all-or-nothing compensation triple, and an aggregate concurrency revision. Deletes only on the governed amend path.';
COMMENT ON TABLE public.hrm_retention_actions IS 'HRM retention actions: append-only ledger of flagged and executed deletions/anonymizations.';
COMMENT ON TABLE public.hrm_retention_rules IS 'HRM retention rules: region scope plus inactivity/consent basis, retain months, and anonymize/delete action. A rule with runs is history-pinned.';
COMMENT ON TABLE public.hrm_retention_runs IS 'HRM retention run ledger: one append-only row per rule evaluation with counts and detail. Append-only.';
COMMENT ON TABLE public.hrm_retention_schedules IS 'HRM retention schedules: one active rule per org category — years counted from completion, termination, or creation.';
COMMENT ON TABLE public.hrm_review_answers IS 'HRM review answer snapshot: sections/questions copied from the template at instantiation so later template edits never rewrite an open cycle.';
COMMENT ON TABLE public.hrm_review_cycles IS 'HRM review runs over a period: draft/open/calibrating/closed with the hrm_process_templates applies_to shape. Cycles are created through the service (never the Setup drawer), so no generated slot projections exist by design. manager_gap_count records in-scope employments with no resolvable manager at open time.';
COMMENT ON TABLE public.hrm_review_events IS 'HRM append-only review lifecycle evidence: instantiated, submitted, calibrated, shared, acknowledged, reopened. Corrections are new rows; updates are refused by trigger.';
COMMENT ON TABLE public.hrm_review_template_questions IS 'HRM review-form prompts: rating, text, or rating_and_text answers; required prompts must be answered before submit.';
COMMENT ON TABLE public.hrm_review_template_sections IS 'HRM ordered review-form sections: competency, goals, or free_text, with an exact-decimal weight.';
COMMENT ON TABLE public.hrm_review_templates IS 'HRM review form configuration: name, rating scale {min,max,labels[]}, and active flag. Editable through the Setup registry; deactivation preserves history. The scale shape CHECK is the single authority on scale content.';
COMMENT ON TABLE public.hrm_reviews IS 'HRM assessments: one per (cycle, employment, kind, reviewer). Calibration never overwrites: calibrated_rating sits beside overall_rating with its reason. Privacy is a service property (grant, subject, reporting line), never storage.';
COMMENT ON TABLE public.hrm_scorecard_attributes IS 'HRM scorecard attributes: the rated attributes of an interview kit, ordered by position. is_focus_default marks the attributes a submission must rate; children of the kit.';
COMMENT ON TABLE public.hrm_scorecard_ratings IS 'HRM scorecard ratings: one rating per (scorecard, attribute); children of the scorecard.';
COMMENT ON TABLE public.hrm_scorecards IS 'HRM interview verdicts: one scorecard per (interview, interviewer). Drafts stay editable; submitted verdicts are immutable except a pure audit touch. private_notes are author-only by the read service.';
COMMENT ON TABLE public.hrm_succession_plans IS 'HRM succession plans: ranked readiness pipelines per position; no candidate self-view exists.';
COMMENT ON TABLE public.hrm_survey_invitations IS 'HRM survey invitations: one consumable token per respondent; anonymous invitations record only that a response happened.';
COMMENT ON TABLE public.hrm_survey_questions IS 'HRM survey questions: ordered question cards with the driver vocabulary heatmaps group by.';
COMMENT ON TABLE public.hrm_survey_responses IS 'HRM survey responses: one row per submission; respondent_link_enc stays null for anonymous surveys and segments below minimum are null.';
COMMENT ON TABLE public.hrm_surveys IS 'HRM surveys: engagement, pulse, onboarding, exit, custom — with the anonymity grade that decides what a response may store.';
COMMENT ON TABLE public.hrm_talent_pool_members IS 'HRM talent pool membership: join rows between pools and candidates, children of both guarded parents.';
COMMENT ON TABLE public.hrm_talent_pools IS 'HRM talent pools: named candidate pools for rediscovery against open requisitions.';
COMMENT ON TABLE public.hrm_talent_reviews IS 'HRM talent reviews: manager 9-box input per report per cycle; HR-only reads, never visible to the subject.';
COMMENT ON TABLE public.hrm_travel_pay_entries IS 'HRM travel-pay entries: same shape as per-diem, separate table so voids never cross between the two kinds.';
COMMENT ON TABLE public.hrm_work_classifications IS 'HRM work classifications: the org''s trade taxonomy. Country-agnostic free text — no pack declares class lists. The journey_classification_id names the journey class an apprentice ratio counts against.';
COMMENT ON TABLE public.hrm_worker_qualifications IS 'HRM held qualifications: one row per employment record (history survives rehire). expires_on is STORED at save; status stores only valid | revoked | pending_verification — expiring/expired are derived at read.';
COMMENT ON TABLE public.it_addizionali_opening_balances IS 'IT addizionali assessed-saldo carry-in: the prior-year regional/municipal assessment per (org, employee, tax year) that the year''s saldo installments withhold. Row presence is the declaration — an explicit zero records a worker with no prior-year Italian employment. Written by the carry-in save under the employee tax-year fence; read with the December settlement factors.';
COMMENT ON TABLE public.nl_report_drafts IS 'HRM AI rails: natural-language report questions with their validated report-engine definitions (never SQL).';
COMMENT ON TABLE public.payroll_anomaly_flags IS 'HRM AI rails: deterministic pre-run payroll/timesheet anomaly flags; block severity refuses the pay-run commit while open.';
COMMENT ON TABLE public.payroll_opening_program_bases IS 'Per-program insurable-earnings carry-in for mid-year adopters: one year-to-date per pack-declared contribution program key. Child of payroll_opening_balances by (org, employee, year) with cascade; the lock, audit and all-zero-delete rules stay on the parent.';
COMMENT ON TABLE public.payroll_opening_sui_wages IS 'Per-state SUI-insurable carry-in for mid-year adopters: one year-to-date per parent carry-in row and US state code. Child of payroll_opening_balances with cascade; the lock, fence, audit and all-zero-delete rules stay on the parent. A state row asserts the transfer determination for those wages.';
COMMENT ON TABLE public.platform_settings IS 'Installation-owned operator configuration: one singleton row for the whole deployment, deliberately org-less so per-org backup, sandbox cloning and org teardown all skip it. Bypass-only RLS; embedded credentials are sealed by engine/src/secrets.ts';
COMMENT ON TABLE public.position_changes IS 'HRM immutable position revision evidence: every position write appends one row with prior image, non-blank reason, and a users row or named system source. Updates and deletes rejected (position_changes_immutable_guard).';
COMMENT ON TABLE public.position_funding IS 'HRM headcount-plan funding: one plan row per position and fiscal period (accounting_periods, budget-style reference) with funded FTE and an optional cost-plan amount. funded_fte >= 0 only: the plan-vs-funded comparison is a service preflight, never a row rejection.';
COMMENT ON TABLE public.position_versions IS 'HRM position versions: title, placement, employer, grade, planned FTE and lifecycle status with half-open effective [effective_from, effective_to) and recorded [recorded_at, recorded_until) intervals. Live versions never overlap per position (position_versions_no_overlap); closed rows immutable (closure guard).';
COMMENT ON COLUMN public.position_versions.job_level_id IS 'Job architecture: the rung this version of the position sits on. Employment versions read their band through the position at the as-of date — band ids are never copied onto employments.';
COMMENT ON TABLE public.positions IS 'HRM stable position identity: one funded establishment slot per org-scoped code. No title, dates, or status: lifecycle lives in position_versions. Code and org immutable (positions_identity_guard).';
COMMENT ON TABLE public.project_geofences IS 'Field time geofences: one circle and one polygon per project; the enforcement place for clock-in location.';
COMMENT ON TABLE public.reporting_relationships IS 'HRM dated reporting lines: line = singular (storage-enforced single live line per subordinate), matrix = simultaneous. Cycles rejected (hrm_reporting_no_cycle).';
COMMENT ON TABLE public.time_clock_events IS 'Field time clock events: device clock actions with the offline idempotency key (org, client_event_id); outside-geofence is recorded and flagged, never refused.';
COMMENT ON TABLE public.time_kiosks IS 'Field time kiosks: shared clock devices; the raw device token is shown once at issue, only the hash is stored.';
COMMENT ON TABLE public.worker_clock_pins IS 'Field time clock PINs: kiosk identity per (org, employee), scrypt-hashed; never a password.';
COMMENT ON TABLE public.worker_employment_versions IS 'HRM employment status versions: half-open effective [effective_from, effective_to) and recorded [recorded_at, recorded_until) intervals. Live versions never overlap per employment (worker_employment_versions_no_overlap + recorded_no_ambiguity); closed rows immutable (closure guard).';
COMMENT ON TABLE public.worker_employments IS 'HRM stable employment identity: one worker party employed by one legal-employer subsidiary. No status, dates, or flags: lifecycle lives in worker_employment_versions. Employer immutable (worker_employments_identity_guard); worker remap only via audited party merge. Canonical employer, no legacy projection: no backfill here; ambiguous source employer/start refused by the one-time migration, never fabricated.';
COMMENT ON CONSTRAINT employee_pay_components_no_active_overlap ON public.employee_pay_components IS 'One active effective window per (org, coalesce(employment_id, employee_party_id), component). The pay run sums every matching row, so an overlap is a double-pay; only storage can arbitrate the concurrent-writer race.';
COMMENT ON INDEX public.hrm_absences_no_double_record IS 'One live row per (org, employment, day). Without it, two concurrent recordings could both pass the application count check and double-count the day; reversal rows (reversal_of set) stay insertable alongside the row they reverse. Rows marked is_pre_guard_legacy predate the guard and are preserved as evidence (provenance in upgrade_legacy_provenance).';
COMMENT ON INDEX public.pay_components_org_country_code IS 'Component code identity: one row per (org, country, code). NULLS NOT DISTINCT keeps the org-level (NULL country) guarantee the old (org, code) index gave, so shared/user codes stay unique; two packs may each own e.g. WCB because their countries differ.';
COMMENT ON INDEX public.pay_components_org_system IS 'Component identity: one row per (org, country, system_key, kind). NULLS NOT DISTINCT keeps the org-level (NULL country) guarantee the three-column index gave; the partial predicate keeps NULL system_key user rows unconstrained, as before. Two packs may each own e.g. income_tax; the seeder absorbs reinstalls on this identity.';
COMMENT ON TRIGGER payment_instructions_posting_claim_fence ON public.payment_instructions IS 'Storage-enforced half of the posting-claim fence: a superseded posting worker cannot mutate instructions after losing authority.';
